// F14, core/14 §2 and §6: every migration runs over a database of every
// older version holding data the app really wrote (testdata, regenerated by
// TestWriteMigrationFixture in internal/integration), and a kill inside a
// migration leaves the previous or the next version, never the middle.

type fixtureValue struct {
	K string `json:"k"`
	V string `json:"v,omitempty"`
}

func (v fixtureValue) arg() any {
	switch v.K {
	case "i":
		n, _ := strconv.ParseInt(v.V, 10, 64)
		return n
	case "f":
		f, _ := strconv.ParseFloat(v.V, 64)
		return f
	case "s":
		return v.V
	case "b":
		b, _ := hex.DecodeString(v.V)
		return b
	}
	return nil
}

type fixture map[string][]map[string]fixtureValue

func loadFixture(t *testing.T) fixture {
	t.Helper()
	body, err := os.ReadFile(filepath.Join("testdata", "migrations", "fixture.json"))
	if err != nil {
		t.Fatal(err)
	}
	var f fixture
	if err := json.Unmarshal(body, &f); err != nil {
		t.Fatal(err)
	}
	return f
}

type column struct {
	name     string
	notNull  bool
	hasValue bool // default or primary key
}

func columnsOf(t *testing.T, db *sql.DB, table string) []column {
	t.Helper()
	rows, err := db.Query(`SELECT name, "notnull", dflt_value IS NOT NULL OR pk > 0 FROM pragma_table_info(?)`, table)
	if err != nil {
		t.Fatal(err)
	}
	defer rows.Close()
	var out []column
	for rows.Next() {
		var c column
		if err := rows.Scan(&c.name, &c.notNull, &c.hasValue); err != nil {
			t.Fatal(err)
		}
		out = append(out, c)
	}
	return out
}

// tableOrder inserts parents before children (foreign keys are on).
var tableOrder = []string{
	"operations", "events", "settings", "game_instances", "instance_targets", "profiles", "active_profiles",
	"profile_snapshots", "app_state", "archives", "mods", "installations", "categories", "instance_rules",
	"instance_overrides", "deployment_manifests", "deployment_entries", "deployment_journals",
	"deployment_journal_actions", "applied_load_orders", "external_unmanaged", "diagnostic_suppressions",
	"diagnostic_presence", "notifications", "instance_plugin_rules",
}

// seed inserts the fixture rows of every table that exists at the current
// version, with the columns that exist. A table whose old shape needs a
// column the fixture lacks (the F3 placeholder of deployment_manifests,
// never written) is skipped. It returns the tables seeded.
func seed(t *testing.T, db *sql.DB, f fixture) []string {
	t.Helper()
	var seeded []string
	for _, table := range tableOrder {
		rows := f[table]
		cols := columnsOf(t, db, table)
		if len(cols) == 0 || len(rows) == 0 {
			continue
		}
		var use []string
		compatible := true
		for _, c := range cols {
			if _, ok := rows[0][c.name]; ok {
				use = append(use, c.name)
			} else if c.notNull && !c.hasValue {
				compatible = false
			}
		}
		if !compatible {
			continue
		}
		q := `INSERT INTO "` + table + `" ("` + strings.Join(use, `","`) + `") VALUES (` + strings.TrimSuffix(strings.Repeat("?,", len(use)), ",") + `)`
		for _, r := range rows {
			args := make([]any, len(use))
			for i, c := range use {
				args[i] = r[c].arg()
			}
			if _, err := db.Exec(q, args...); err != nil {
				t.Fatalf("seed %s: %v", table, err)
			}
		}
		seeded = append(seeded, table)
	}
	return seeded
}

func openAt(t *testing.T, path string, version int) *sql.DB {
	t.Helper()
	db, err := OpenUnmigrated(context.Background(), path)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { db.Close() })
	if err := migrateTo(context.Background(), db, version); err != nil {
		t.Fatal(err)
	}
	return db
}

func checkIntegrity(t *testing.T, db *sql.DB) {
	t.Helper()
	var check string
	if err := db.QueryRow(`PRAGMA integrity_check`).Scan(&check); err != nil || check != "ok" {
		t.Fatalf("integrity_check = %s %v", check, err)
	}
	rows, err := db.Query(`PRAGMA foreign_key_check`)
	if err != nil {
		t.Fatal(err)
	}
	defer rows.Close()
	if rows.Next() {
		t.Fatal("foreign_key_check found orphans")
	}
}

// rowsOf reads a table as the fixture shape, for comparison.
func rowsOf(t *testing.T, db *sql.DB, table string) []map[string]fixtureValue {
	t.Helper()
	rows, err := db.Query(`SELECT * FROM "` + table + `" ORDER BY rowid`)
	if err != nil {
		t.Fatal(err)
	}
	defer rows.Close()
	cols, _ := rows.Columns()
	var out []map[string]fixtureValue
	for rows.Next() {
		vals := make([]any, len(cols))
		ptrs := make([]any, len(cols))
		for i := range vals {
			ptrs[i] = &vals[i]
		}
		if err := rows.Scan(ptrs...); err != nil {
			t.Fatal(err)
		}
		r := map[string]fixtureValue{}
		for i, c := range cols {
			switch x := vals[i].(type) {
			case nil:
				r[c] = fixtureValue{K: "n"}
			case int64:
				r[c] = fixtureValue{K: "i", V: strconv.FormatInt(x, 10)}
			case float64:
				r[c] = fixtureValue{K: "f", V: fmt.Sprint(x)}
			case string:
				r[c] = fixtureValue{K: "s", V: x}
			case []byte:
				r[c] = fixtureValue{K: "b", V: hex.EncodeToString(x)}
			}
		}
		out = append(out, r)
	}
	return out
}

func TestMigrationsFromEveryOldVersion(t *testing.T) {
	ctx := context.Background()
	f := loadFixture(t)
	latest := LatestSchemaVersion()
	for from := 1; from < latest; from++ {
		t.Run("v"+strconv.Itoa(from), func(t *testing.T) {
			path := filepath.Join(t.TempDir(), "state.db")
			db := openAt(t, path, from)
			seeded := seed(t, db, f)
			if err := Migrate(ctx, db); err != nil {
				t.Fatalf("migrate v%d → v%d: %v", from, latest, err)
			}
			if v, _ := SchemaVersion(ctx, db); v != latest {
				t.Fatalf("version = %d", v)
			}
			checkIntegrity(t, db)
			for _, table := range seeded {
				got := rowsOf(t, db, table)
				want := f[table]
				if len(got) != len(want) {
					t.Fatalf("%s: %d rows after migrating, %d before", table, len(got), len(want))
				}
				for i := range want {
					for c, v := range want[i] {
						// From before mods and profiles existed, the backfill of
						// migration 0007 cannot find what a mod event is about
						// (a real database of that age has no such event).
						if table == "events" && c == "instance_id" && !slices.Contains(seeded, "mods") {
							continue
						}
						if got[i][c] != v {
							t.Fatalf("%s row %d column %s: %+v, the app wrote %+v", table, i, c, got[i][c], v)
						}
					}
				}
			}
			assertReadable(t, db, seeded)
		})
	}
}

// assertReadable reads the migrated data through the repositories, as the
// app does on its first start after an update.
func assertReadable(t *testing.T, db *sql.DB, seeded []string) {
	t.Helper()
	ctx := context.Background()
	if !slices.Contains(seeded, "game_instances") {
		return
	}
	list, err := NewGameInstanceRepository(db).List(ctx)
	if err != nil || len(list) != 1 {
		t.Fatalf("instances = %v %v", list, err)
	}
	inst := list[0]
	if slices.Contains(seeded, "profiles") {
		active, err := NewProfileRepository(db).Active(ctx, inst.ID)
		if err != nil {
			t.Fatal(err)
		}
		if _, err := NewProfileRepository(db).Get(ctx, active); err != nil {
			t.Fatal(err)
		}
	}
	if slices.Contains(seeded, "mods") {
		mods, err := NewModRepository(db).ListByInstance(ctx, inst.ID)
		if err != nil || len(mods) != 2 {
			t.Fatalf("mods = %d %v", len(mods), err)
		}
	}
	if slices.Contains(seeded, "deployment_entries") {
		h, err := NewManifestRepository(db).Header(ctx, inst.ID)
		if err != nil || h.Entries == 0 {
			t.Fatalf("manifest = %+v %v", h, err)
		}
	}
}

// schemaOf is the schema as SQLite stores it, to compare a database with
// the reference of its version.
func schemaOf(t *testing.T, db *sql.DB) []string {
	t.Helper()
	rows, err := db.Query(`SELECT type || ' ' || name || ' ' || COALESCE(sql, '') FROM sqlite_master WHERE name NOT LIKE 'sqlite_%' ORDER BY type, name`)
	if err != nil {
		t.Fatal(err)
	}
	defer rows.Close()
	var out []string
	for rows.Next() {
		var s string
		_ = rows.Scan(&s)
		out = append(out, s)
	}
	return out
}

const (
	envMigDB    = "MO_MIG_DB"
	envMigKill  = "MO_MIG_KILL"
	envMigStage = "MO_MIG_STAGE"
)

// TestMigrationKillHelper is the child of TestKillDuringMigration: it
// migrates and dies inside (or right after) one migration.
func TestMigrationKillHelper(t *testing.T) {
	path := os.Getenv(envMigDB)
	if path == "" {
		t.Skip("child process of TestKillDuringMigration")
	}
	kill, _ := strconv.Atoi(os.Getenv(envMigKill))
	committed := os.Getenv(envMigStage) == "after"
	migrationHook = func(v int, c bool) {
		if v == kill && c == committed {
			os.Exit(3)
		}
	}
	db, err := OpenUnmigrated(context.Background(), path)
	if err != nil {
		t.Fatal(err)
	}
	_ = Migrate(context.Background(), db)
	t.Fatal("the hook did not fire")
}

// core/14 §6: "Matar o processo durante uma migration: ao reabrir, o banco
// está na versão anterior ou na nova, nunca no meio."
func TestKillDuringMigration(t *testing.T) {
	if os.Getenv(envMigDB) != "" {
		t.Skip("running as the child")
	}
	ctx := context.Background()
	f := loadFixture(t)
	latest := LatestSchemaVersion()
	reference := map[int][]string{}
	for v := 1; v <= latest; v++ {
		reference[v] = schemaOf(t, openAt(t, filepath.Join(t.TempDir(), "ref.db"), v))
	}
	for v := 2; v <= latest; v++ {
		for _, stage := range []string{"before", "after"} {
			t.Run(fmt.Sprintf("v%d-%s-commit", v, stage), func(t *testing.T) {
				path := filepath.Join(t.TempDir(), "state.db")
				db := openAt(t, path, 1)
				seed(t, db, f)
				db.Close()

				cmd := exec.Command(os.Args[0], "-test.run=^TestMigrationKillHelper$", "-test.count=1")
				cmd.Env = append(os.Environ(), envMigDB+"="+path, envMigKill+"="+strconv.Itoa(v), envMigStage+"="+stage)
				out, err := cmd.CombinedOutput()
				if exit, ok := err.(*exec.ExitError); !ok || exit.ExitCode() != 3 {
					t.Fatalf("child: %v\n%s", err, out)
				}

				db2, err := OpenUnmigrated(ctx, path)
				if err != nil {
					t.Fatal(err)
				}
				defer db2.Close()
				got, err := SchemaVersion(ctx, db2)
				if err != nil {
					t.Fatal(err)
				}
				want := v - 1
				if stage == "after" {
					want = v
				}
				if got != want {
					t.Fatalf("version after the kill = %d, want %d", got, want)
				}
				if s := schemaOf(t, db2); !slices.Equal(s, reference[got]) {
					t.Fatalf("schema is not v%d's:\n%v\nwant\n%v", got, s, reference[got])
				}
				checkIntegrity(t, db2)
				if err := Migrate(ctx, db2); err != nil {
					t.Fatalf("migrate after the kill: %v", err)
				}
				if s := schemaOf(t, db2); !slices.Equal(s, reference[latest]) {
					t.Fatal("schema after finishing differs from a fresh database")
				}
				if n := len(rowsOf(t, db2, "operations")); n != len(f["operations"]) {
					t.Fatalf("operations = %d", n)
				}
			})
		}
	}
}
